import Link from"next/link";import{notFound,redirect}from"next/navigation";import{requireUser}from"@/lib/auth/session";import{getRankedRun}from"@/lib/challenges/service";import{getChallengeDetail}from"@/lib/challenges/queries";import{challengePhase}from"@/lib/challenges/policy";import{percentile}from"@/lib/gamification/ranking";
export default async function Page({params}:{params:Promise<{runId:string}>}){const[{runId},u]=await Promise.all([params,requireUser()]);const r=await getRankedRun(runId,u.id);if(!r)notFound();if(r.run.status!=="COMPLETED")redirect(`/ranking/challenges/run/${runId}`);const d=await getChallengeDetail(r.challenge.id,u.id);if(!d)notFound();const rank=d.own?.rank;const pct=rank?percentile(rank,d.participants):null;const closed=challengePhase(r.challenge)==="CLOSED";return <main className="min-h-screen bg-slate-50 p-6"><div className="mx-auto max-w-3xl"><h1 className="text-3xl font-black">Kết quả {r.challenge.titleVi}</h1><div className="mt-6 grid gap-3 sm:grid-cols-3"><article className="rounded-2xl bg-white p-5"><p>Tổng</p><strong className="text-3xl">{r.run.totalScore}/{r.challenge.type==="FULL_200"?200:100}</strong></article>{r.challenge.type==="FULL_200"&&<><article className="rounded-2xl bg-white p-5"><p>Listening</p><strong className="text-3xl">{r.run.listeningScore}/100</strong></article><article className="rounded-2xl bg-white p-5"><p>Reading</p><strong className="text-3xl">{r.run.readingScore}/100</strong></article></>}</div><p className="mt-5 font-bold">Hạng: {rank?`#${rank} / ${d.participants}`:"Ẩn khỏi bảng công khai"}{pct?` · Top ${pct}%`:""}</p>{closed?<section className="mt-8"><h2 className="text-xl font-black">Xem lại chi tiết</h2>{r.sessions.map(s=><Link className="mr-3 mt-3 inline-flex rounded-lg border p-3 font-bold" href={`/practice/${s.id}/results`} key={s.id}>Part {s.part}</Link>)}</section>:<p className="mt-8 rounded-xl bg-amber-50 p-4 font-semibold">Chi tiết đáp án sẽ mở khi thử thách kết thúc.</p>}<p className="mt-8 text-sm text-slate-600">Điểm thô; không phải điểm TOEIC quy đổi. Không có /495 hoặc /990.</p></div></main>}
